"""v0.3 log renderer (spec v0.3 §4). Frozen; ships in the authoring packet.

Standalone: standard library only, plus the sibling packet module ``tokenizer`` (imported lazily so
the harness can also import this file as ``agent_loop_lab.v03.renderer``).

    blocks = render_session(rawops, session_id)   # rawops: list of RawOp dicts (RawOp.to_dict())

One block per event: a header line, then at most 6 body lines (hunk lines, error line, workspace line).
"""

from __future__ import annotations

import difflib
import hashlib
import json
import random
from datetime import datetime, timezone
from typing import Any, Mapping, Sequence

try:  # packet layout: tokenizer.py next to this file
    import tokenizer as _tok  # type: ignore
except ImportError:  # harness layout
    from . import tokenizer as _tok  # type: ignore

HEADER_MAX_TOKENS = 64
BODY_MAX_LINES = 6
LINE_MAX_TOKENS = 20  # excluding the line-marker token
HUNK_MAX_LINES = 5
TRUNC = "TRUNC"

FIELD_BUDGETS = {"tests": 24, "body": 16, "paths": 16, "query": 12}

VALIDATE_FAMILIES = ("run_tests", "build", "lint")
DIGEST_DROPS = ("digest_before", "digest_after")


def _get(op: Mapping[str, Any] | Any, key: str, default: Any = None) -> Any:
    if isinstance(op, Mapping):
        return op.get(key, default)
    return getattr(op, key, default)


def _ascii(text: str) -> str:
    return "".join(ch if 32 <= ord(ch) < 127 else "?" for ch in str(text))


def _ntok(text: str) -> int:
    return len(_tok.tokenize_block(text))


def _fit(text: str, budget: int) -> str:
    """ASCII-sanitise ``text`` and cut it to at most ``budget`` tokens, ending with TRUNC when cut.

    The cut keeps the source text up to the end of the last kept token, so the kept part reads
    exactly as it would uncut; a space before TRUNC keeps it a separate word."""
    text = _ascii(text)
    spans = _tok.tokenize_spans(text)
    if len(spans) <= budget:
        return text
    keep = max(0, budget - 1)
    kept = text[: spans[keep - 1][3]] if keep else ""
    return (kept + " " + TRUNC) if kept else TRUNC


def canonical_json(obj: Any) -> str:
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=True, default=str)


def render_rng(op: Mapping[str, Any] | Any) -> random.Random:
    d = op if isinstance(op, Mapping) else op.to_dict()
    seed = int(hashlib.sha256((canonical_json(d) + ":render").encode()).hexdigest()[:16], 16)
    return random.Random(seed)


def _clock(ts: str | None) -> str:
    if not ts:
        return "?"
    t = datetime.fromisoformat(ts)
    if t.tzinfo is not None:
        t = t.astimezone(timezone.utc)
    return f"{t:%H:%M:%S}.{t.microsecond // 1000:03d}"


def _q(v: Any) -> str:
    return "?" if v is None else str(v)


def hunk_id(session_id: str, path: str, lines: Sequence[str]) -> str:
    if not lines:
        return "h0"
    text = "\n".join(lines)
    return "h" + hashlib.sha256(f"{session_id}:hunk:{path}:{text}".encode("utf-8")).hexdigest()[:10]


def diff_hunks(before: str | None, after: str | None) -> list[tuple[list[str], list[str]]]:
    """(removed lines, added lines) per hunk of the n=0 unified diff."""
    a = [] if before is None else before.split("\n")
    b = [] if after is None else after.split("\n")
    lines = list(difflib.unified_diff(a, b, "a", "b", lineterm="", n=0))[2:]
    hunks: list[tuple[list[str], list[str]]] = []
    for ln in lines:
        if ln.startswith("@@"):
            hunks.append(([], []))
        elif hunks and ln.startswith("-"):
            hunks[-1][0].append(ln[1:])
        elif hunks and ln.startswith("+"):
            hunks[-1][1].append(ln[1:])
    return hunks


def _status(op: Any) -> str:
    family, outcome = _get(op, "family"), _get(op, "outcome")
    dropped = set(_get(op, "dropped") or ())
    val = _get(op, "validation")
    if family == "poll_status":
        status = "ready" if outcome == "SUCCESS" else ("pending" if outcome == "NEUTRAL" else "error")
    elif family in VALIDATE_FAMILIES:
        status = "FAILED" if outcome == "ERROR" else "ok"
    else:
        status = "error" if outcome == "ERROR" else "ok"
    if val is not None:
        p = "?" if "validation_passed" in dropped else _q(val.get("passed"))
        t = "?" if "validation_total" in dropped else _q(val.get("total"))
        status += f" {p}/{t} passed"
    tin = "?" if "input_tokens" in dropped else _q(_get(op, "input_tokens"))
    tout = "?" if "output_tokens" in dropped else _q(_get(op, "output_tokens"))
    return f"-> {status} in={tin} out={tout}"


def _fields(op: Any, rng: random.Random) -> str:
    family = _get(op, "family")
    target = _get(op, "target")
    args = _get(op, "args") or {}
    dropped = set(_get(op, "dropped") or ())
    parts: list[str] = []
    if family in ("read_file", "list_dir", "edit_file"):
        parts.append(f"path={target}")
        if family == "read_file" and (args.get("line_start") is not None or args.get("line_end") is not None):
            parts.append(f"lines={_q(args.get('line_start'))}-{_q(args.get('line_end'))}")
    elif family == "write_file":
        parts.append(f"path={target}")
    elif family == "search":
        parts.append(f"scope={target}")
        parts.append('query="' + _fit(str(args.get("query", "")), FIELD_BUDGETS["query"]) + '"')
        if args.get("limit") is not None:
            parts.append(f"limit={args['limit']}")
    elif family == "revert":
        paths = target if isinstance(target, (list, tuple)) else [target]
        parts.append("paths=" + _fit(",".join(str(p) for p in paths), FIELD_BUDGETS["paths"]))
    elif family == "run_tests":
        suite = "?" if "validation_suite" in dropped else target
        parts.append(f"suite={suite}")
        if args.get("tests"):
            parts.append("tests=" + _fit(",".join(str(t) for t in args["tests"]), FIELD_BUDGETS["tests"]))
    elif family in ("build", "lint"):
        suite_dropped = "validation_suite" in dropped and _get(op, "validation") is not None
        parts.append(f"target={'?' if suite_dropped else target}")
    elif family == "http_call":
        t = target or {}
        parts.append(f"{t.get('method', '?')} https://{t.get('host', '?')}{t.get('path_template', '')}")
        if args.get("body") is not None:
            parts.append("body=" + _fit(str(args["body"]), FIELD_BUDGETS["body"]))
        parts.append(f"req={rng.getrandbits(32):08x}")
    elif family == "poll_status":
        parts.append(f"resource={target}")
        if args.get("backoff") is not None:
            parts.append(f"backoff={args['backoff']}")
    elif family in ("plan", "ask", "yield"):
        parts.append(f"action={args.get('action_type', '?')}")
    else:
        parts.append(f"target={target}")
    return " ".join(parts)


def _header(op: Any, rng: random.Random) -> str:
    head = f"{_clock(_get(op, 'timestamp'))} {_get(op, 'family')}"
    suffix = _status(op)
    fields = _ascii(_fields(op, rng))
    room = HEADER_MAX_TOKENS - _ntok(head) - _ntok(suffix)
    if _ntok(fields) > room:
        fields = _fit(fields, room)
    return _ascii(f"{head} {fields} {suffix}")


def _line(marker: str, text: str) -> str:
    return "  " + marker + " " + _fit(_ascii(text), LINE_MAX_TOKENS)


def render_event(op: Any, session_id: str) -> str:
    rng = render_rng(op)
    header = _header(op, rng)
    hunk_lines: list[str] = []
    for ch in sorted(_get(op, "changed") or [], key=lambda c: c["path"]):
        # One line per changed file (spec v0.3 r2 §4.3): all removed lines vs all added lines of the
        # n=0 diff, so the number of hunks inside a file is not shown.
        hunks = diff_hunks(ch.get("before"), ch.get("after"))
        if not hunks:
            continue
        removed = [ln for r, _ in hunks for ln in r]
        added = [ln for _, a in hunks for ln in a]
        path = ch["path"]
        hunk_lines.append(f"{path} {hunk_id(session_id, path, removed)} > {hunk_id(session_id, path, added)}")
    tail: list[str] = []
    if _get(op, "outcome") == "ERROR":
        dropped = set(_get(op, "dropped") or ())
        loc = _get(op, "error_location")
        if "failure" in dropped:
            cls, loc_s, line = "?", "?", "?"
        else:
            cls = _q(_get(op, "error_class"))
            loc_s = _q(loc)
            line = "?" if loc is None else str(int(hashlib.sha256(f"{session_id}:{loc}".encode()).hexdigest()[:4], 16) % 900 + 1)
        noise = f"pid {rng.randint(1000, 99999)}" if rng.random() < 0.5 else f"0x{rng.getrandbits(32):08x}"
        tail.append(("!", f"{cls} at {loc_s}:{line} ({noise})"))
    if set(_get(op, "dropped") or ()) & set(DIGEST_DROPS):
        tail.append(("[", "workspace untracked]"))
    max_hunks = min(HUNK_MAX_LINES, BODY_MAX_LINES - len(tail))
    if len(hunk_lines) > max_hunks:
        omitted = len(hunk_lines) - (max_hunks - 1)
        hunk_lines = hunk_lines[: max_hunks - 1] + [f"{TRUNC} {omitted}"]
    body = [_line("@", h) for h in hunk_lines] + [_line(m, t) for m, t in tail]
    return "\n".join([header] + body)


def render_session(rawops: Sequence[Any], session_id: str) -> list[str]:
    return [render_event(op, session_id) for op in rawops]

"""``./fwd request.json``: one metered forward pass (docs/V04_WSP_KERNEL.md §1 principle 2, §3 ``forward``).

Installed as ``tools/hn_kernel/fwd.py`` (read-only, checked by ``hypaqwen.wsp.install.verify_tools``
before every session and in the audit; the ``./fwd`` wrapper refuses to run if ``tools/`` is
writable); imports only the standard library and numpy. ``./fwd`` runs without the ``./py`` guard,
so it never imports anything from an author-writable directory: the kernel dir and the author dir
are removed from ``sys.path`` before the first non-builtin import, and ``protocol`` is loaded by
explicit file path from this file's own directory after its standard-library imports are loaded.
The interpreter install stays on ``sys.path`` even inside the author dir (the read-only author venv,
``AUTHOR_DIR/.venv``). The ``./fwd`` wrapper runs it as ``.venv/bin/python -I -B``.

1. Reads ``request.json``, which must be a regular file (no symlink anywhere below the author dir)
   under the author dir and at most ``MAX_REQUEST_BYTES``, and validates it with the server's own
   schema (``protocol.validate_forward_request``; or ``validate_disclosed_request`` for a WSP-B
   ``{"disclosed_windows": [...], "model": ...}`` request). A malformed request never reaches the
   server and costs nothing.
2. Sends one ``forward`` (or ``forward_disclosed``) op to the forward socket.
3. Writes ``output/<phase>/fwd/<call id>/``: ``response.json`` (label logits, logsumexp, argmax and
   top-k token ids, deltas for ``both``, the budget), ``request.json`` (a copy) and one ``.npy``
   per requested activation, ``<model>.s<session index>.<hidden|mlp_act>.L<layer>.npy`` of shape
   ``[n_windows, d]``.
4. Prints a short summary: counts, class indices and token totals. It never prints vocabulary strings.

The only argument is the request path. The author dir and the socket come from the launcher's
environment (``HN_AUTHOR_DIR``, ``HN_FWD_SOCKET``; the author's Bash hook cannot set variables), else
from the install layout (``AUTHOR_DIR/tools/hn_kernel/fwd.py``, ``AUTHOR_DIR/.kernel/fwd.sock``).

Exit status: 0 on success, 1 if the server refused the request (nothing charged), 2 if the request
was invalid before sending.
"""

# No ``from __future__`` import: it would be the first module looked up on sys.path.
import os  # frozen, already loaded at start-up
import sys  # builtin

_HERE = os.path.dirname(os.path.realpath(__file__))


def _author_dir() -> str:
    env = os.environ.get("HN_AUTHOR_DIR")
    return os.path.realpath(env) if env else os.path.dirname(os.path.dirname(_HERE))


def _inside(path: str, root: str) -> bool:
    return path == root or path.startswith(root.rstrip(os.sep) + os.sep)


def _scrub_sys_path() -> None:
    """Drop '' (the cwd), the kernel dir and the author dir from sys.path: nothing author-writable is importable.

    The interpreter install is kept even when it lies inside the author dir: the author venv is
    ``AUTHOR_DIR/.venv`` (read-only), and its site-packages holds numpy.
    """
    author = _author_dir()
    installs = [os.path.realpath(p) for p in (sys.prefix, sys.base_prefix, sys.exec_prefix, sys.base_exec_prefix)
                if p and os.path.realpath(p) != os.sep]

    def keep(p: str) -> bool:
        r = os.path.realpath(p)
        if _inside(r, _HERE):
            return False
        return not _inside(r, author) or any(_inside(r, i) for i in installs)

    sys.path[:] = [p for p in sys.path if p and keep(p)]


if not __package__:  # run as the ./fwd script (as a package module, the harness's own sys.path is left alone)
    _scrub_sys_path()

import argparse  # noqa: E402
import contextlib  # noqa: E402,F401  (protocol's imports, loaded before protocol itself)
import json  # noqa: E402
import math  # noqa: E402,F401
import re  # noqa: E402
import socket  # noqa: E402,F401
import stat  # noqa: E402
import struct  # noqa: E402,F401
import typing  # noqa: E402,F401
from pathlib import Path  # noqa: E402
from typing import Sequence  # noqa: E402

import numpy as np  # noqa: E402


def _sibling(name: str):
    """``<this dir>/<name>.py`` loaded by explicit path, never through sys.path (shared via sys.modules)."""
    import importlib.util

    key = f"hn_kernel_{name}"
    mod = sys.modules.get(key)
    if mod is None:
        spec = importlib.util.spec_from_file_location(key, os.path.join(_HERE, f"{name}.py"))
        mod = importlib.util.module_from_spec(spec)
        sys.modules[key] = mod
        try:
            spec.loader.exec_module(mod)
        except BaseException:
            del sys.modules[key]
            raise
    return mod


if __package__:
    from . import protocol as P
else:
    P = _sibling("protocol")

AUTHOR_ENV = "HN_AUTHOR_DIR"
SOCKET_ENV = "HN_FWD_SOCKET"
MAX_REQUEST_BYTES = 8 << 20  # the per-request token cap (50,000) is far below this


class _BadRequest(Exception):
    pass


def _relative_inside(path: Path, author: Path) -> Path:
    """``path`` relative to ``author``; raises if it is not lexically inside (``..`` collapsed)."""
    lex = Path(os.path.abspath(path))
    for base in (Path(os.path.abspath(author)), Path(os.path.realpath(author))):
        try:
            rel = lex.relative_to(base)
        except ValueError:
            continue
        if ".." not in rel.parts:
            return rel
    raise _BadRequest("the request file must be inside the author dir")


def _no_links(author: Path, rel: Path) -> Path:
    """``realpath(author) / rel`` with every component below the author dir checked not to be a symlink."""
    root = Path(os.path.realpath(author))
    cur = root
    for part in rel.parts:
        cur = cur / part
        try:
            st = os.lstat(cur)
        except FileNotFoundError:
            break  # nothing below exists yet, so nothing below is a symlink
        if stat.S_ISLNK(st.st_mode):
            raise _BadRequest(f"{rel} goes through a symlink")
    return root / rel


def read_request(path: Path, author: Path) -> tuple[str, str]:
    """``(text, path relative to the author dir)`` of a request file, or ``_BadRequest``.

    The file must be a regular file inside the author dir (not in ``.kernel/``), reached without
    symlinks, at most MAX_REQUEST_BYTES. Error messages never echo the file's contents.
    """
    rel = _relative_inside(path, author)
    if rel.parts and rel.parts[0] == ".kernel":
        raise _BadRequest("the request file may not be in .kernel/")
    full = _no_links(author, rel)
    try:
        fd = os.open(full, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NONBLOCK", 0))
    except OSError as e:
        raise _BadRequest(f"cannot open {rel}: {e.strerror}") from None
    try:
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode):
            raise _BadRequest(f"{rel} is not a regular file")
        if st.st_size > MAX_REQUEST_BYTES:
            raise _BadRequest(f"{rel} is {st.st_size} bytes, over the {MAX_REQUEST_BYTES}-byte limit")
        f = os.fdopen(fd, "rb")
    except BaseException:
        os.close(fd)
        raise
    with f:
        data = f.read(MAX_REQUEST_BYTES + 1)
    if len(data) > MAX_REQUEST_BYTES:
        raise _BadRequest(f"{rel} is over the {MAX_REQUEST_BYTES}-byte limit")
    try:
        return data.decode("utf-8"), str(rel)
    except UnicodeDecodeError:
        raise _BadRequest(f"{rel} is not UTF-8") from None


def _send(sock_path: Path, req: dict, request_rel: str, disclosed: bool) -> tuple[dict, dict[str, np.ndarray]]:
    if disclosed:
        header = {"op": "forward_disclosed", "args": {"window_ids": req["disclosed_windows"], "model": req["model"]}}
    else:
        header = {"op": "forward", "args": {"request": req, "request_path": request_rel}}
    sock = P.connect(sock_path)
    try:
        P.send_msg(sock, header)
        return P.recv_msg(sock)
    finally:
        sock.close()


def _out_dir(author: Path, phase: str, call_id: int) -> Path:
    """``author/output/<phase>/fwd/<call id>``, refusing a symlinked component on the way."""
    rel = Path("output") / phase / "fwd" / str(call_id)
    try:
        return _no_links(author, rel)
    except _BadRequest:
        raise ValueError(f"{rel.parent} goes through a symlink; refusing to write there") from None


def _write(out_dir: Path, result: dict, arrays: dict[str, np.ndarray], request_text: str, request_rel: str) -> dict:
    out_dir.mkdir(parents=True, exist_ok=False)  # a call id is never reused
    files = {}
    for key, a in arrays.items():
        if not re.fullmatch(r"[A-Za-z0-9_.]+", key):
            raise ValueError(f"bad array key from server {key!r}")
        np.save(out_dir / f"{key}.npy", a)
        files[key] = {"file": f"{key}.npy", "shape": list(a.shape)}
    response = {**result, "request_file": request_rel, "arrays": files}
    (out_dir / "response.json").write_text(json.dumps(response, indent=1) + "\n", encoding="utf-8")
    (out_dir / "request.json").write_text(request_text, encoding="utf-8")
    return response


def summary(response: dict, out_dir: Path) -> str:
    b = response["budget"]
    lines = [f"fwd call {response['call_id']}: model={response['model']} edit={response['edit_hash'][:12]} "
             f"tokens={response['tokens']} used={b['tokens_used']} left={b['tokens_left']} -> {out_dir}"]
    kinds = ("edited", "original") if response["model"] == "both" else (response["model"],)
    for s in response["sessions"][:20]:
        argmax = {k: s[k]["label_argmax"] for k in kinds}
        part = " ".join(f"{k}={v}" for k, v in argmax.items())
        if "delta" in s:
            part += f" label_flips={s['delta']['label_argmax_flips']} token_flips={s['delta']['argmax_flips']}"
        lines.append(f"  {s['id']}: label argmax (class index) {part}")
    if len(response["sessions"]) > 20:
        lines.append(f"  ... {len(response['sessions']) - 20} more sessions in response.json")
    if response["arrays"]:
        lines.append(f"  arrays: {len(response['arrays'])} .npy files")
    return "\n".join(lines)


def main(argv: Sequence[str] | None = None) -> int:
    ap = argparse.ArgumentParser(prog="./fwd", description="Run one metered forward pass request.",
                                 allow_abbrev=False)
    ap.add_argument("request", type=Path)
    args = ap.parse_args(argv)
    author = Path(_author_dir())
    sock_path = Path(os.environ.get(SOCKET_ENV) or author / ".kernel" / "fwd.sock")
    try:
        text, request_rel = read_request(args.request, author)
        raw = json.loads(text)
        disclosed = isinstance(raw, dict) and "disclosed_windows" in raw
        req = P.validate_disclosed_request(raw) if disclosed else P.validate_forward_request(raw)
    except (_BadRequest, json.JSONDecodeError, RecursionError, P.RequestError) as e:
        print(f"fwd: invalid request {args.request}: {e}", file=sys.stderr)
        return 2
    header, arrays = _send(sock_path, req, request_rel, disclosed)
    if not header.get("ok"):
        err = header.get("error") or {}
        print(f"fwd: refused ({err.get('type')}): {err.get('message')}", file=sys.stderr)
        return 1
    result = header["result"]
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]*", str(result["phase"])) or not isinstance(result["call_id"], int):
        raise ValueError("bad phase or call id from server")
    out_dir = _out_dir(author, result["phase"], result["call_id"])
    response = _write(out_dir, result, arrays, text, request_rel)
    print(summary(response, out_dir.relative_to(os.path.realpath(author))))
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""PreToolUse hook of the v0.4 weight-author session (docs/V04_WSP_KERNEL.md §7). Standard library only.

Installed read-only as ``AUTHOR_DIR/tools/hn_hook/hook_bash.py`` by the prepare script and registered in
the session settings (``settings_wsp_a.json`` / ``settings_wsp_b.json``) as::

    "$CLAUDE_PROJECT_DIR"/.venv/bin/python -I -B "$CLAUDE_PROJECT_DIR"/tools/hn_hook/hook_bash.py PHASE

Claude Code shows the session the hook's command line verbatim when the hook blocks a call
("PreToolUse:Bash hook error: [<command>]: <reason>"; checked with a real ``claude -p`` session), so the
command names no harness path: only ``$CLAUDE_PROJECT_DIR``, unexpanded. The author dir is this file's
grandparent's parent. The input is Claude Code's PreToolUse JSON on stdin (``tool_name``, ``tool_input``,
``cwd``, ``session_id``, ``transcript_path``, ``hook_event_name``, ...).

Decision: exit 0 with no output lets the call go on to the permission rules (it never approves anything
by itself); exit 2 blocks it with the reason on stderr. A hook that fails any other way fails *open*
(Claude Code runs the call), so every error inside the hook is turned into a block, and the launcher
runs this hook on sample calls before each session.

Rules (every rule is also checked by the session audit, which loads this file by path):

* ``Bash``: the command must match ``^\\./(py|fwd) [^;&|<>`$\\n]+$`` as a whole string (``re.fullmatch``,
  so a trailing newline does not slip past ``$``), and also, stricter: every space-separated word is
  made of ``[A-Za-z0-9_./=:,+@%-]`` (no quotes, globs, ``~``, braces, backslashes, ``#``, ``!``, ``(``,
  tabs or carriage returns), no word has a ``..`` component or is absolute, and
  - ``./fwd REQUEST.json``: exactly one argument, a ``.json`` file inside ``output/<phase>/``;
  - ``./py SCRIPT.py [ARGS]``: the script is a ``.py`` file inside ``output/<phase>/``;
    ``./py -m py_compile FILE.py`` likewise; ``./py -c`` and any other ``-m`` are refused;
  - ``run_in_background`` is refused: ``claude -p`` waits for background tasks, so one long ``./py`` would
    keep the session, the model server and ``caffeinate`` alive, and a background ``./py`` editor would run
    beside the session's ``./fwd`` calls.
* ``Write`` / ``Edit`` / ``MultiEdit`` / ``NotebookEdit``: the target, after resolving symlinks, lies inside
  ``output/<phase>/`` and not inside ``output/<phase>/fwd/`` (the forward tool's records; compared
  case-insensitively, since APFS resolves ``FWD/`` to ``fwd/``).
* ``Read`` / ``Glob`` / ``Grep``: every path argument, after resolving symlinks, lies inside the author
  dir and not inside ``.kernel/``; a ``Glob`` pattern or ``Grep`` glob is relative and has no ``..``.
* The session's ``cwd`` must be the author dir. Any other tool is refused.

CLI: ``hook_bash.py PHASE [AUTHOR_DIR]`` (the second argument is for tests).
"""

import json
import os
import re
import sys

COMMAND_RE = re.compile(r"\./(py|fwd) [^;&|<>`$\n]+")  # the contract's regex, applied with fullmatch
WORD_RE = re.compile(r"[A-Za-z0-9_./=:,+@%-]+")
PHASE_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.-]*")
READ_TOOLS = ("Read", "Glob", "Grep")
WRITE_TOOLS = ("Write", "Edit", "MultiEdit", "NotebookEdit")
KIT_TOOLS = READ_TOOLS + WRITE_TOOLS + ("Bash",)


def _inside(path, root):
    root = root.rstrip(os.sep)
    return path == root or path.startswith(root + os.sep)


def _real(path, author):
    """``path`` (absolute, or relative to the author dir) with symlinks resolved."""
    return os.path.realpath(path if os.path.isabs(path) else os.path.join(author, path))


def _relative_word(word, what):
    """A command argument that names a file: relative, no ``..`` component, not an option."""
    if word.startswith("-"):
        return f"{what} may not start with '-'"
    if word.startswith("/"):
        return f"{what} must be a relative path"
    if ".." in word.split("/"):
        return f"{what} may not contain '..'"
    return None


def _in_phase(word, author, phase, suffix, what):
    bad = _relative_word(word, what)
    if bad:
        return bad
    phase_dir = os.path.realpath(os.path.join(author, "output", phase))
    path = _real(word, author)
    if not _inside(path, phase_dir) or path == phase_dir:
        return f"{what} must lie inside output/{phase}/"
    if not path.endswith(suffix):
        return f"{what} must be a {suffix} file"
    return None


def check_bash(command, author, phase):
    """None if ``command`` is an allowed ``./py`` / ``./fwd`` call, else the reason it is refused."""
    if not isinstance(command, str) or not COMMAND_RE.fullmatch(command):
        return ("only a single './py output/{p}/SCRIPT.py [ARGS]' or './fwd output/{p}/REQUEST.json' command "
                "is allowed per Bash call: no ';', '&&', '||', pipes, redirection, backticks, '$', newlines "
                "or other programs").format(p=phase)
    words = command.split(" ")
    if any(not WORD_RE.fullmatch(w) for w in words[1:]):
        return ("arguments may contain only letters, digits and _ . / = : , + @ % - separated by single spaces "
                "(no quotes, globs, ~, braces, backslashes, tabs or other shell syntax)")
    tool, args = words[0], words[1:]
    if tool == "./fwd":
        if len(args) != 1:
            return "./fwd takes exactly one argument: the request file"
        return _in_phase(args[0], author, phase, ".json", "the request file")
    if args[0] == "-c":
        return "./py -c is not supported: write the code to a file under output/{p}/ and run it".format(p=phase)
    if args[0] == "-m":
        if len(args) != 3 or args[1] != "py_compile":
            return "the only -m form is: ./py -m py_compile output/{p}/FILE.py".format(p=phase)
        return _in_phase(args[2], author, phase, ".py", "the file")
    return _in_phase(args[0], author, phase, ".py", "the script")


def check_write(path, author, phase):
    if not isinstance(path, str) or not path:
        return "missing file path"
    phase_dir = os.path.realpath(os.path.join(author, "output", phase))
    target = _real(path, author)
    if not _inside(target, phase_dir) or target == phase_dir:
        return f"writes are allowed only inside output/{phase}/"
    if _inside(target.casefold(), os.path.join(phase_dir, "fwd").casefold()):
        return f"output/{phase}/fwd/ holds the forward tool's records and is written only by ./fwd"
    return None


def check_read_path(path, author):
    if not isinstance(path, str):
        return "bad path argument"
    if not path:
        return None
    target = _real(path, os.path.realpath(author))
    root = os.path.realpath(author)
    if not _inside(target, root):
        return "reads are allowed only inside this directory"
    if _inside(target, os.path.join(root, ".kernel")):
        return ".kernel/ holds the kernel's sockets and cannot be read"
    return None


def _pattern(p, what):
    if not isinstance(p, str):
        return f"bad {what}"
    if p.startswith(("/", "~")) or ".." in re.split(r"[/\\]", p):
        return f"the {what} must be relative to this directory and may not contain '..'"
    return None


def decide(event, author, phase):
    """None to let the call proceed to the permission rules, else the reason it is blocked."""
    if not PHASE_RE.fullmatch(phase or ""):
        return "hook misconfigured: bad phase"
    author = os.path.realpath(author)
    if not isinstance(event, dict):
        return "hook input is not an object"
    cwd = event.get("cwd")
    if not isinstance(cwd, str) or os.path.realpath(cwd) != author:
        return "the session must run in the author directory"
    tool, inp = event.get("tool_name"), event.get("tool_input")
    if not isinstance(inp, dict):
        return "hook input has no tool_input object"
    if tool == "Bash":
        if inp.get("run_in_background"):
            return ("run_in_background is not allowed: run ./py and ./fwd in the foreground, one call at a time "
                    "(make a long job shorter instead)")
        return check_bash(inp.get("command"), author, phase)
    if tool in WRITE_TOOLS:
        return check_write(inp.get("file_path") or inp.get("notebook_path"), author, phase)
    if tool == "Read":
        return check_read_path(inp.get("file_path") or "", author) if inp.get("file_path") else "missing file path"
    if tool == "Glob":
        return check_read_path(inp.get("path") or "", author) or _pattern(inp.get("pattern"), "pattern")
    if tool == "Grep":
        bad = check_read_path(inp.get("path") or "", author)
        if bad is None and inp.get("glob") is not None:
            bad = _pattern(inp.get("glob"), "glob")
        return bad
    return f"tool {tool!r} is not part of the author kit (Read, Glob, Grep, Write, Edit, Bash)"


def default_author_dir():
    """``AUTHOR_DIR`` for the installed copy ``AUTHOR_DIR/tools/hn_hook/hook_bash.py``."""
    return os.path.dirname(os.path.dirname(os.path.dirname(os.path.realpath(__file__))))


def main(argv):
    try:
        if len(argv) not in (1, 2):
            raise ValueError("usage: hook_bash.py PHASE [AUTHOR_DIR]")
        phase = argv[0]
        author = argv[1] if len(argv) == 2 else default_author_dir()
        event = json.loads(sys.stdin.read())
        reason = decide(event, author, phase)
    except Exception as exc:  # noqa: BLE001 - fail closed: any error blocks the call
        reason = f"hook error ({type(exc).__name__}); the call is blocked"
    if reason is None:
        return 0
    print(f"refused: {reason}", file=sys.stderr)
    return 2


if __name__ == "__main__":
    try:
        code = main(sys.argv[1:])
    except BaseException:  # noqa: BLE001
        code = 2
    sys.exit(code)

"""WSP author client (docs/V04_WSP_KERNEL.md §4), copied into the author dir as ``tools/hn_kernel/client.py``.

Imports only the standard library, numpy and torch (plus, optionally, ``tokenizers`` for ``tok``),
never ``transformers`` or ``hypaqwen``: it runs in the author's guarded ``./py`` interpreter. It
never loads a model and has no ``forward``; forward passes are the separate ``./fwd`` tool.

    from wsp import load, load_original, save_edit, save_label_rows, drop_edit, edited, edit_hash, budget, \\
        NAMES, SHAPES, ARCH, LABEL_IDS, CLASS_NAMES, tok

The module-level functions use one connection to the kernel socket, opened on first use:
``$HN_KERNEL_SOCKET``, else ``AUTHOR_DIR/.kernel/kernel.sock``. ``NAMES``, ``SHAPES``, ``ARCH``,
``LABEL_IDS`` and ``CLASS_NAMES`` are fetched from the server on first access. Tensor names are the
checkpoint's (``model.language_model.*``).

The weight-only helpers (``svd``, ``head_slice``, ``top_writers``, ``project_out``, ``rank1``,
``zero_head``, ``label_lens``, ``dla``, ``diff_means``, ``control_direction``) are plain torch. None
of them saves anything; pass their results to ``save_edit`` yourself.
"""

from __future__ import annotations

import atexit
import contextlib  # noqa: F401  (protocol's imports, loaded before protocol itself)
import json  # noqa: F401
import math  # noqa: F401
import os
import socket  # noqa: F401
import struct  # noqa: F401
import sys
from pathlib import Path
from typing import Any, NamedTuple, Sequence

import numpy as np
import torch


def _sibling(name: str):
    """``<this dir>/<name>.py`` loaded by explicit path, never through sys.path (shared via sys.modules).

    The ``./py`` wrapper imports this module before entering the guard (for ``init_tok``), so it
    must not make anything in an author-writable directory importable: it never touches sys.path.
    """
    import importlib.util

    key = f"hn_kernel_{name}"
    mod = sys.modules.get(key)
    if mod is None:
        spec = importlib.util.spec_from_file_location(key, Path(__file__).resolve().parent / f"{name}.py")
        mod = importlib.util.module_from_spec(spec)
        sys.modules[key] = mod
        try:
            spec.loader.exec_module(mod)
        except BaseException:
            del sys.modules[key]
            raise
    return mod


if __package__:
    from . import protocol as _P
else:  # loaded by path as tools/hn_kernel/client.py
    _P = _sibling("protocol")

SOCKET_ENV = "HN_KERNEL_SOCKET"
TOKENIZER_ENV = "HN_TOKENIZER"
AUTHOR_ENV = "HN_AUTHOR_DIR"
# Set by the launcher; else the install layout AUTHOR_DIR/tools/hn_kernel/client.py.
AUTHOR_DIR = Path(os.environ.get(AUTHOR_ENV) or Path(__file__).resolve().parent.parent.parent).resolve()
PREFIX = "model.language_model."
EMBED = PREFIX + "embed_tokens.weight"
FINAL_NORM = PREFIX + "norm.weight"


class KernelError(RuntimeError):
    """The server refused or failed a request; the edit state and the meter are unchanged."""


class EditRefused(KernelError):
    pass


class BudgetRefused(KernelError):
    pass


class RequestError(KernelError):
    pass


class QuotaRefused(KernelError):
    """The phase's weight-load quota is used up (server §3): no more distinct layer tensors can be loaded."""


_ERRORS = {"EditRefused": EditRefused, "BudgetRefused": BudgetRefused, "RequestError": RequestError,
           "QuotaRefused": QuotaRefused}


class EditReceipt(NamedTuple):
    """What one save changed (server §3). Label-row receipts count over the ``[4, d]`` block."""

    name: str
    changed_entries: int
    changed_rows: int
    changed_cols: int
    rel_frobenius: float
    delta_rank: int
    sha256: str
    label_rows: bool
    bf16_changed_entries: int
    edit_hash: str


def _wire(t: Any, what: str) -> np.ndarray:
    if isinstance(t, np.ndarray):
        t = torch.from_numpy(t)
    if not isinstance(t, torch.Tensor):
        raise EditRefused(f"{what}: expected a torch.Tensor, not {type(t).__name__}")
    if t.dtype != torch.float32:
        raise EditRefused(f"{what}: dtype {t.dtype}, expected torch.float32 (edits are fp32; cast explicitly)")
    return t.detach().cpu().contiguous().numpy()


class KernelClient:
    """One connection to the kernel socket. The server serves one connection at a time."""

    def __init__(self, path: Path | str | None = None, timeout: float | None = None):
        self.path = Path(path or os.environ.get(SOCKET_ENV) or AUTHOR_DIR / ".kernel" / "kernel.sock")
        self._sock = _P.connect(self.path, timeout)

    def close(self) -> None:
        self._sock.close()

    def call(self, op: str, tensors: dict[str, np.ndarray] | None = None, **args) -> tuple[Any, dict[str, np.ndarray]]:
        _P.send_msg(self._sock, {"op": op, "args": args}, tensors)
        header, out = _P.recv_msg(self._sock)
        if not header.get("ok"):
            err = header.get("error") or {}
            raise _ERRORS.get(err.get("type"), KernelError)(err.get("message", "unknown error"))
        return header.get("result"), out

    def names(self) -> tuple[str, ...]:
        return tuple(self.call("names")[0])

    def shapes(self) -> dict[str, tuple[int, ...]]:
        return {k: tuple(v) for k, v in self.call("shapes")[0].items()}

    def arch(self) -> dict:
        return self.call("arch")[0]

    def load(self, name: str) -> torch.Tensor:
        return torch.from_numpy(self.call("load", name=name)[1]["tensor"])

    def load_original(self, name: str) -> torch.Tensor:
        return torch.from_numpy(self.call("load_original", name=name)[1]["tensor"])

    def label_rows(self, original: bool = False) -> torch.Tensor:
        return torch.from_numpy(self.call("load_label_rows", original=original)[1]["rows"])

    def save_edit(self, name: str, tensor: torch.Tensor) -> EditReceipt:
        return EditReceipt(**self.call("save_edit", {"tensor": _wire(tensor, name)}, name=name)[0])

    def save_label_rows(self, rows: torch.Tensor) -> EditReceipt:
        return EditReceipt(**self.call("save_label_rows", {"rows": _wire(rows, "label rows")})[0])

    def drop_edit(self, name: str) -> bool:
        return bool(self.call("drop_edit", name=name)[0]["dropped"])

    def edited(self) -> list[str]:
        return list(self.call("edited")[0])

    def edit_hash(self) -> str:
        return self.call("edit_hash")[0]

    def budget(self) -> dict:
        return self.call("budget")[0]

    def load_quota(self) -> dict:
        return self.call("load_quota")[0]


# ---------------------------------------------------------------- module-level API

_client: KernelClient | None = None
_cache: dict[str, Any] = {}


def connect(path: Path | str | None = None) -> KernelClient:
    """(Re)open the module's connection, e.g. to a socket other than the default.

    The server's metadata is fetched again; ``tok`` is kept: it comes from the packet, and the ``./py``
    launcher builds it before the guard, which refuses the tokenizer's file read afterwards.
    """
    global _client
    if _client is not None:
        _client.close()
    _client = KernelClient(path)
    for k in [k for k in _cache if k != "tok"]:
        del _cache[k]
    return _client


def _c() -> KernelClient:
    return _client if _client is not None else connect()


@atexit.register
def _close() -> None:
    if _client is not None:
        _client.close()


def init_tok(path: Path | str | None = None):
    """The packet's ``tokenizers.Tokenizer`` (``$HN_TOKENIZER``, else ``AUTHOR_DIR/packet/qwen/tokenizer.json``).

    None if ``tokenizers`` is not installed or the file is missing. The ``./py`` wrapper calls this
    before entering the guard, which forbids reading other files afterwards.
    """
    p = Path(path or os.environ.get(TOKENIZER_ENV) or AUTHOR_DIR / "packet" / "qwen" / "tokenizer.json")
    try:
        from tokenizers import Tokenizer
    except ImportError:
        return None
    return Tokenizer.from_file(str(p)) if p.is_file() else None


_LAZY = {
    "NAMES": lambda: _c().names(),
    "SHAPES": lambda: _c().shapes(),
    "ARCH": lambda: _c().arch(),
    "LABEL_IDS": lambda: tuple(__getattr__("ARCH")["label_ids"]),
    "CLASS_NAMES": lambda: tuple(__getattr__("ARCH")["class_names"]),
    "tok": init_tok,
}


def __getattr__(name: str) -> Any:  # PEP 562: metadata is fetched on first access
    if name in _LAZY:
        if name not in _cache:
            _cache[name] = _LAZY[name]()
        return _cache[name]
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")


def load(name: str) -> torch.Tensor:
    """The current tensor: your edit if there is one, else the original (fp32, CPU)."""
    return _c().load(name)


def load_original(name: str) -> torch.Tensor:
    return _c().load_original(name)


def label_rows(original: bool = False) -> torch.Tensor:
    """The four label-word rows of the tied embedding, ``[4, d]`` in CLASS_NAMES order."""
    return _c().label_rows(original)


def save_edit(name: str, tensor: torch.Tensor) -> EditReceipt:
    """Replace a whole tensor. Refused outside the edit scope; equal to the original drops the edit."""
    return _c().save_edit(name, tensor)


def save_label_rows(rows: torch.Tensor) -> EditReceipt:
    return _c().save_label_rows(rows)


def drop_edit(name: str) -> bool:
    return _c().drop_edit(name)


def edited() -> list[str]:
    return _c().edited()


def edit_hash() -> str:
    return _c().edit_hash()


def budget() -> dict:
    """``{tokens_used, tokens_left, requests}`` of the phase's forward-pass budget."""
    return _c().budget()


def load_quota() -> dict:
    """``{bytes_used, bytes_left, bytes_quota, tensors}`` of the phase's weight-load quota.

    ``load``/``load_original`` of a layer tensor (anything but the embedding and the final norm)
    you have not loaded before in this phase draws on it; loading it again is free.
    """
    return _c().load_quota()


# ---------------------------------------------------------------- weight-only helpers


class HeadSlice(NamedTuple):
    """One head's block of a weight matrix: ``weight == load(name).narrow(dim, start, stop - start)``."""

    name: str
    dim: int
    start: int
    stop: int
    weight: torch.Tensor


def _f32(x: Any) -> torch.Tensor:
    return torch.as_tensor(np.asarray(x) if not isinstance(x, torch.Tensor) else x).float()


def _2d(w: torch.Tensor) -> torch.Tensor:
    return w.reshape(w.shape[0], -1)


def svd(name: str, k: int) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Top-``k`` ``U [m, k]``, ``S [k]``, ``Vh [k, n]`` of the current tensor (as ``[shape[0], -1]``), in float64."""
    u, s, vh = torch.linalg.svd(_2d(load(name)).double(), full_matrices=False)
    return u[:, :k].float(), s[:k].float(), vh[:k].float()


def _head_table(layer: int, head: int) -> dict[str, tuple[str, int, int, int]]:
    a = __getattr__("ARCH")
    if a["layer_types"][layer] == "full_attention":
        nh, nkv, hd = a["num_attention_heads"], a["num_key_value_heads"], a["head_dim"]
        if not 0 <= head < nh:
            raise ValueError(f"layer {layer} has query heads 0..{nh - 1}")
        kv = head // (nh // nkv)  # GQA: query head -> its shared key/value head
        step = 2 * hd if a.get("attn_output_gate") else hd  # q_proj rows per head: [q (hd), gate (hd)]
        t = {"q": ("self_attn.q_proj.weight", 0, head * step, head * step + hd),
             "k": ("self_attn.k_proj.weight", 0, kv * hd, (kv + 1) * hd),
             "v": ("self_attn.v_proj.weight", 0, kv * hd, (kv + 1) * hd),
             "o": ("self_attn.o_proj.weight", 1, head * hd, (head + 1) * hd)}
        if a.get("attn_output_gate"):
            t["gate"] = ("self_attn.q_proj.weight", 0, head * step + hd, (head + 1) * step)
        return t
    nk, nv = a["linear_num_key_heads"], a["linear_num_value_heads"]
    dk, dv = a["linear_key_head_dim"], a["linear_value_head_dim"]
    if not 0 <= head < nv:
        raise ValueError(f"layer {layer} has value heads 0..{nv - 1}")
    kh, kd = head // (nv // nk), nk * dk  # value head -> its key head; in_proj_qkv rows are [q | k | v]
    qkv = "linear_attn.in_proj_qkv.weight"
    return {"q": (qkv, 0, kh * dk, (kh + 1) * dk),
            "k": (qkv, 0, kd + kh * dk, kd + (kh + 1) * dk),
            "v": (qkv, 0, 2 * kd + head * dv, 2 * kd + (head + 1) * dv),
            "z": ("linear_attn.in_proj_z.weight", 0, head * dv, (head + 1) * dv),
            "b": ("linear_attn.in_proj_b.weight", 0, head, head + 1),
            "a": ("linear_attn.in_proj_a.weight", 0, head, head + 1),
            "o": ("linear_attn.out_proj.weight", 1, head * dv, (head + 1) * dv)}


def head_slice(layer: int, head: int, kind: str, W: torch.Tensor | None = None) -> HeadSlice:
    """One head's rows (``q``/``k``/``v``/``gate``/``z``/``a``/``b``) or output columns (``o``).

    Full-attention layers: ``head`` is a query head (``k``/``v`` give its shared KV head). Gated
    DeltaNet layers: ``head`` is a value head (``q``/``k`` give its key head). ``W`` defaults to
    ``load(name)``; pass a tensor you are editing to slice that instead.
    """
    table = _head_table(layer, head)
    if kind not in table:
        raise ValueError(f"kind must be one of {sorted(table)} for layer {layer}")
    rest, dim, start, stop = table[kind]
    name = f"{PREFIX}layers.{layer}.{rest}"
    W = load(name) if W is None else W
    return HeadSlice(name, dim, start, stop, W.narrow(dim, start, stop - start).clone())


def zero_head(layer: int, head: int) -> tuple[str, torch.Tensor]:
    """``(name, W')``: the layer's output projection with this head's input columns zeroed."""
    s = head_slice(layer, head, "o")
    W = load(s.name)
    W.narrow(1, s.start, s.stop - s.start).zero_()
    return s.name, W


def top_writers(name: str, direction: Any, k: int = 10) -> tuple[torch.Tensor, torch.Tensor]:
    """The ``k`` units whose weight vectors most align with ``direction``: ``(indices, signed scores)``, by |score|.

    If ``direction`` lives in the output space (``shape[0]``: ``o_proj``, ``down_proj``, ``out_proj``)
    the units are columns (what each input unit writes); otherwise in the input space (``shape[1]``,
    e.g. embedding rows) they are rows.
    """
    W, d = _2d(load(name)), _f32(direction).reshape(-1)
    if W.shape[0] == d.numel():
        scores = W.T @ d
    elif W.shape[1] == d.numel():
        scores = W @ d
    else:
        raise ValueError(f"{name} {tuple(W.shape)} has no dimension of size {d.numel()}")
    idx = scores.abs().topk(min(k, scores.numel())).indices
    return idx, scores[idx]


def project_out(W: torch.Tensor, u: Any, cols: Sequence[int] | None = None, alpha: float = 1.0) -> torch.Tensor:
    """``W - alpha * u (mask * (u^T W))`` with ``u`` normalised to unit length (``u`` in the row space).

    ``cols`` limits the projection to those columns; ``alpha=1`` removes the ``u`` component exactly.
    """
    W = _f32(W)
    u = _f32(u).reshape(-1)
    u = u / torch.linalg.vector_norm(u)
    coef = u @ _2d(W)
    if cols is not None:
        mask = torch.zeros_like(coef)
        mask[list(cols)] = 1.0
        coef = coef * mask
    return W - alpha * torch.outer(u, coef).reshape(W.shape)


def rank1(W: torch.Tensor, a: Any, b: Any) -> torch.Tensor:
    """``W + a b^T``."""
    W = _f32(W)
    return W + torch.outer(_f32(a).reshape(-1), _f32(b).reshape(-1)).reshape(W.shape)


def _final_norm() -> tuple[torch.Tensor, float]:
    if "_final_norm" not in _cache:
        _cache["_final_norm"] = (load(FINAL_NORM), float(__getattr__("ARCH")["rms_norm_eps"]))
    return _cache["_final_norm"]


def label_lens(h: Any, original: bool = False) -> torch.Tensor:
    """The four label logits a residual ``h [..., d]`` would give: final ``(1 + w)`` RMSNorm, then the label rows.

    For ``./fwd`` hidden states (``hidden.L<n>.npy``); at the last layer this reproduces the readout.
    """
    w, eps = _final_norm()
    h = _f32(h)
    x = h * torch.rsqrt(h.pow(2).mean(-1, keepdim=True) + eps) * (1.0 + w)
    return x @ label_rows(original).T


def dla(vec: Any, resid: Any = None, original: bool = False) -> torch.Tensor:
    """Direct label attribution of a residual contribution ``vec [..., d]``: ``(vec * (1 + w)) / rms(resid) @ rows^T``.

    ``resid`` is the full final residual the contribution sits in (its RMS freezes the norm's scale);
    without it the RMS factor is 1.
    """
    w, eps = _final_norm()
    x = _f32(vec) * (1.0 + w)
    if resid is not None:
        r = _f32(resid)
        x = x * torch.rsqrt(r.pow(2).mean(-1, keepdim=True) + eps)
    return x @ label_rows(original).T


