def explore(ctx, k=3, j0=0):
    s = ctx.s
    for j in range(k):
        kind = hnum(s.sid, "ex", j0 + j, hi=4)
        if kind == 0:
            s.list_dir(ctx.P["dirs"][j % 2])
        elif kind == 1:
            s.search(ctx.P["dirs"][j % 2], ctx.query(j0 + j), limit=(5 + 5 * (j % 2)) if j % 3 == 0 else None)
        elif kind == 2:
            p = ctx.path()
            s.read(p, lines=(10 * (j + 1), 10 * (j + 1) + 60))
